    for (var i = 0; i < messages.length; i++) {
      final file = _fileName(messages[i]);
      (await _env.writeFile(
        '${_readDir(agentId)}/$file',
        jsonEncode(messages[i].toJson()),
      )).getOrThrow();
      (await _env.remove('$inbox/$file', force: true)).getOrThrow();
