        // state, `_scheduled` is the delayed-message store.
        if (mbDir.name.startsWith('.') || mbDir.name.startsWith('_')) {
          continue;
        }
        final idMarker = (await _env.readTextFile(
          '${mbDir.path}/.id',
        )).valueOrNull?.trim();
        final id = (idMarker != null && idMarker.isNotEmpty)
            ? idMarker
