  @override
  Future<List<AgentMessage>> peek(String agentId) => _inner.peek(agentId);

  @override
  Future<List<AgentMessage>> drain(String agentId) => _inner.drain(agentId);

  @override
  Future<List<MailboxEntry>> directory() => _inner.directory();
}

